SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" DESC NULLS FIRST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."title" AS "title", "_root.ar.root.comments"."comments" AS "comments", "_root.or.author"."author" AS "author"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("public"."article"."author_id") = (('3')::integer))   ORDER BY "id" DESC NULLS FIRST  ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.author.base"."id" AS "id", "_root.or.author.base"."name" AS "name", "_root.or.author.ar.author.articles"."articles" AS "articles"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.or.author.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("articles" ORDER BY "root.or.author.ar.author.articles.pg.id" ASC NULLS LAST), '[]' ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.author.ar.author.articles.base"."id" AS "id"       ) AS "_e"      ) ) AS "articles", "_root.or.author.ar.author.articles.base"."id" AS "root.or.author.ar.author.articles.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.or.author.base"."id") = ("author_id"))   ORDER BY "id" ASC NULLS LAST LIMIT 2 ) AS "_root.or.author.ar.author.articles.base"    ORDER BY "root.or.author.ar.author.articles.pg.id" ASC NULLS LAST  ) AS "_root.or.author.ar.author.articles"      ) AS "_root.or.author.ar.author.articles" ON ('true')      ) AS "_root.or.author" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.comments.base"."id" AS "id", "_root.ar.root.comments.base"."body" AS "body"       ) AS "_e"      ) ) AS "comments" FROM  (SELECT  *  FROM "public"."comment"  WHERE ((("_root.base"."id") = ("article_id")) AND (("public"."comment"."article_id") = (('9')::integer)))     ) AS "_root.ar.root.comments.base"      ) AS "_root.ar.root.comments"      ) AS "_root.ar.root.comments" ON ('true')    ORDER BY "root.pg.id" DESC NULLS FIRST  ) AS "_root"      
